  "content": "package io.jsonwebtoken.impl;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.jsonwebtoken.JwtBuilder;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.SignatureAlgorithm;

import javax.crypto.Mac;
import java.nio.charset.StandardCharsets;
import java.security.Key;
import java.util.Base64;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.Map;

public class DefaultJwtBuilder implements JwtBuilder {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private String subject;
    private Date issuedAt;
    private Date expiration;
    private final Map<String, Object> claims = new LinkedHashMap<>();
    private Key key;
    private SignatureAlgorithm alg;

    @Override
    public JwtBuilder setSubject(String subject) {
        this.subject = subject;
        return this;
    }

    @Override
    public JwtBuilder claim(String name, Object value) {
        this.claims.put(name, value);
        return this;
    }

    @Override
    public JwtBuilder setIssuedAt(Date issuedAt) {
        this.issuedAt = issuedAt;
        return this;
    }

    @Override
    public JwtBuilder setExpiration(Date expiration) {
        this.expiration = expiration;
        return this;
    }

    @Override
    public JwtBuilder signWith(Key key, SignatureAlgorithm alg) {
        this.key = key;
        this.alg = alg;
        return this;
    }

    @Override
    public String compact() {
        if (key == null) {
            throw new JwtException("A signing key must be specified.");
        }
        Map<String, Object> header = new LinkedHashMap<>();
        header.put("alg", alg == null ? "none" : alg.name());
        header.put("typ", "JWT");

        Map<String, Object> payload = new LinkedHashMap<>(claims);
        if (subject != null) {
            payload.put("sub", subject);
        }
        if (issuedAt != null) {
            payload.put("iat", issuedAt.getTime() / 1000L);
        }
        if (expiration != null) {
            payload.put("exp", expiration.getTime() / 1000L);
        }

        try {
            Base64.Encoder enc = Base64.getUrlEncoder().withoutPadding();
            String h = enc.encodeToString(MAPPER.writeValueAsBytes(header));
            String p = enc.encodeToString(MAPPER.writeValueAsBytes(payload));
            String signingInput = h + "." + p;
